import React, { useCallback, useState } from 'react';
import { LiveboardEmbed } from '@thoughtspot/visual-embed-sdk/react';
import { RuntimeFilterOp } from '@thoughtspot/visual-embed-sdk';
import { THOUGHTSPOT_LIVEBOARD_ID, TOP_HEADER_PX } from '../config/thoughtspot';
import { useTier } from '../config/TierContext';
import { formatThoughtSpotEmbedError } from '../utils/thoughtspotErrors';

const BST_BLUE = '#1D3FA8';
const EMBED_MIN_H = `calc(100vh - ${TOP_HEADER_PX}px - 260px)`;

// ─── Date period helpers ────────────────────────────────────────────────────

interface DatePeriod { id: string; label: string; startDate: () => string; }

const DATE_PERIODS: DatePeriod[] = [
  { id: '30d',  label: 'Last 30 Days',   startDate: () => offset({ days: -30 }) },
  { id: '3m',   label: 'Last 3 Months',  startDate: () => offset({ months: -3 }) },
  { id: '12m',  label: 'Last 12 Months', startDate: () => offset({ months: -12 }) },
  { id: 'ytd',  label: 'Year to Date',   startDate: () => `${new Date().getFullYear()}-01-01` },
];

function offset({ days = 0, months = 0 }): string {
  const d = new Date();
  d.setMonth(d.getMonth() + months);
  d.setDate(d.getDate() + days);
  return d.toISOString().split('T')[0];
}

// ─── Select filter groups — add real values from your ThoughtSpot model ─────

interface SelectGroup { column: string; label: string; values: string[]; }

const SELECT_GROUPS: SelectGroup[] = [
  { column: 'Plant',    label: 'Plant',    values: [] },
  { column: 'Driver',   label: 'Driver',   values: [] },
  { column: 'Vehicle',  label: 'Vehicle',  values: [] },
  { column: 'Customer', label: 'Customer', values: [] },
];

// ─── Chip components ─────────────────────────────────────────────────────────

function FilterChip({ label, active, onClick }: { label: string; active: boolean; onClick: () => void }) {
  return (
    <button
      type="button"
      onClick={onClick}
      style={{
        padding: '5px 13px',
        borderRadius: 16,
        border: `1px solid ${active ? '#ffffff' : 'rgba(255,255,255,0.3)'}`,
        background: active ? '#ffffff' : 'rgba(255,255,255,0.12)',
        color: active ? BST_BLUE : 'rgba(255,255,255,0.85)',
        fontSize: 12.5,
        fontWeight: active ? 700 : 400,
        cursor: 'pointer',
        whiteSpace: 'nowrap',
        transition: 'all 0.12s ease',
        display: 'flex',
        alignItems: 'center',
        gap: 4,
      }}
    >
      {active && <span style={{ fontSize: 10 }}>✓</span>}
      {label}
    </button>
  );
}

// ─── Page component ───────────────────────────────────────────────────────────

interface LiveboardTabPageProps {
  title: string;
  description?: string;
  tabId: string;
}

export default function LiveboardTabPage({ title, description, tabId }: LiveboardTabPageProps) {
  const { hiddenActions, disabledActions } = useTier();

  // Date period — default to Last 12 Months (matches liveboard default)
  const [datePeriod, setDatePeriod] = useState('12m');

  // Multi-select state for each dimension
  const [selected, setSelected] = useState<Record<string, string[]>>({});

  const toggle = (column: string, value: string) =>
    setSelected(prev => {
      const cur = prev[column] ?? [];
      return { ...prev, [column]: cur.includes(value) ? cur.filter(v => v !== value) : [...cur, value] };
    });

  const clearAll = () => { setDatePeriod('12m'); setSelected({}); };
  const hasFilters = datePeriod !== '12m' || Object.values(selected).some(v => v.length > 0);

  // Build runtime filters
  const selectedPeriod = DATE_PERIODS.find(p => p.id === datePeriod)!;
  const runtimeFilters = [
    { columnName: 'Date', operator: RuntimeFilterOp.GE, values: [selectedPeriod.startDate()] },
    ...SELECT_GROUPS
      .filter(g => (selected[g.column] ?? []).length > 0)
      .map(g => ({ columnName: g.column, operator: RuntimeFilterOp.IN, values: selected[g.column] })),
  ];

  // Re-mount embed when any filter changes
  const embedKey = `${tabId}-${datePeriod}-${JSON.stringify(selected)}`;

  const onError = useCallback((err: { data?: { errorMessage?: string }; message?: string }) => {
    console.error(`[ThoughtSpot – ${title}]`, formatThoughtSpotEmbedError(err), err);
  }, [title]);

  return (
    <div style={{ backgroundColor: BST_BLUE, minHeight: `calc(100vh - ${TOP_HEADER_PX}px)` }}>

      {/* Blue header */}
      <div style={{ padding: '1.75rem 2.5rem 0' }}>
        <div style={{ fontSize: 10, fontWeight: 700, letterSpacing: '0.1em', textTransform: 'uppercase', color: 'rgba(255,255,255,0.55)', marginBottom: 6 }}>BST Media</div>
        <div style={{ display: 'flex', alignItems: 'flex-start', justifyContent: 'space-between', flexWrap: 'wrap', gap: 12 }}>
          <div>
            <h1 style={{ fontSize: 26, fontWeight: 800, color: '#ffffff', margin: 0 }}>{title}</h1>
            {description && <p style={{ fontSize: 14, color: 'rgba(255,255,255,0.7)', margin: '4px 0 0', maxWidth: 600 }}>{description}</p>}
          </div>
          {hasFilters && (
            <button type="button" onClick={clearAll} style={{ background: 'rgba(255,255,255,0.12)', border: '1px solid rgba(255,255,255,0.3)', color: 'rgba(255,255,255,0.8)', borderRadius: 8, padding: '6px 14px', fontSize: 12, cursor: 'pointer' }}>
              Reset filters
            </button>
          )}
        </div>
      </div>

      {/* Native filter bar */}
      <div style={{ padding: '1rem 2.5rem 1.25rem', display: 'flex', flexDirection: 'column', gap: 8 }}>

        {/* Date row */}
        <div style={{ display: 'flex', alignItems: 'center', gap: 8, flexWrap: 'wrap' }}>
          <span style={{ fontSize: 11, fontWeight: 600, color: 'rgba(255,255,255,0.45)', textTransform: 'uppercase', letterSpacing: '0.07em', minWidth: 48 }}>Date</span>
          {DATE_PERIODS.map(p => (
            <FilterChip key={p.id} label={p.label} active={datePeriod === p.id} onClick={() => setDatePeriod(p.id)} />
          ))}
        </div>

        {/* Dimension rows — only shown when values are configured */}
        {SELECT_GROUPS.map(group => (
          group.values.length > 0 && (
            <div key={group.column} style={{ display: 'flex', alignItems: 'center', gap: 8, flexWrap: 'wrap' }}>
              <span style={{ fontSize: 11, fontWeight: 600, color: 'rgba(255,255,255,0.45)', textTransform: 'uppercase', letterSpacing: '0.07em', minWidth: 48 }}>
                {group.label}
              </span>
              {group.values.map(value => (
                <FilterChip
                  key={value}
                  label={value}
                  active={(selected[group.column] ?? []).includes(value)}
                  onClick={() => toggle(group.column, value)}
                />
              ))}
            </div>
          )
        ))}
      </div>

      {/* Embed card — ThoughtSpot header (tabs + filter bar) hidden */}
      <div style={{ padding: '0 2.5rem 2rem' }}>
        <div style={{ backgroundColor: '#ffffff', borderRadius: 12, minHeight: EMBED_MIN_H, overflow: 'visible' }}>
          <LiveboardEmbed
            key={embedKey}
            liveboardId={THOUGHTSPOT_LIVEBOARD_ID}
            activeTabId={tabId}
            fullHeight
            hiddenActions={hiddenActions}
            disabledActions={disabledActions}
            hideLiveboardHeader
            onError={onError}
            runtimeFilters={runtimeFilters}
            isLiveboardStylingAndGroupingEnabled
            additionalFlags={{ enable2ColumnLayout: true }}
            style={{ width: '100%', minHeight: EMBED_MIN_H, display: 'block', border: 'none' }}
          />
        </div>
      </div>
    </div>
  );
}
